    1:{solid:'#e9363e',light:'#f5a3a7'},2:{solid:'#f28a31',light:'#ffd1a5'},3:{solid:'#f4d52f',light:'#fff0a0'},
    4:{solid:'#55be45',light:'#b7e3ac'},5:{solid:'#38afc8',light:'#afe2eb'},6:{solid:'#6341b4',light:'#c1b3e3'},
